clamp_trace.cpp.src:
#include <iostream>
#include <vector>

int clamp_score(int s) {
    if (s < 0) {
        return 0;
    }
    if (s > 100) {
        return 100;
    }
    return s;
}

int main() {
    std::vector<int> inputs{50, -7, 100, 250, 0};
    std::vector<int> expected{50, 0, 100, 100, 1};
    for (std::size_t i = 0; i < inputs.size(); ++i) {
        int actual = clamp_score(inputs[i]);
        int want = expected[i];
        std::cout << inputs[i] << ' ' << want << ' ' << actual << ' '
                  << (actual == want ? "PASS" : "FAIL") << '\n';
    }
}

