edge_tests.cpp.src:
#include <iostream>
#include <limits>
#include <string>
#include <vector>

int biggest(const std::vector<int>& v) {
    int best = v[0];
    for (int x : v) {
        if (x > best) {
            best = x;
        }
    }
    return best;
}

int passed = 0;
int failed = 0;

void check(const std::string& name, int expected, int actual) {
    if (expected == actual) {
        ++passed;
    } else {
        ++failed;
        std::cout << "FAIL " << name << ": expected " << expected
                  << ", got " << actual << '\n';
    }
}

int main() {
    const int top = std::numeric_limits<int>::max();
    check("ordinary", 9, biggest({3, 9, 4}));
    check("just one", 5, biggest({5}));
    check("all negative", -2, biggest({-5, -2, -8}));
    check("all the same", 4, biggest({4, 4, 4}));
    check("biggest last", 8, biggest({1, 2, 8}));
    check("largest int", top, biggest({0, top, -1}));
    std::cout << passed << " passed, " << failed << " failed" << '\n';
}

