#include <string>

int count_vowels(const std::string& word) {
    int n = 0;
    for (char c : word) {
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            ++n;
        }
    }
    return n;
}

void check(const std::string& word, int expected) {
    int actual = count_vowels(word);
    std::cout << (expected == actual ? "PASS " : "FAIL ") << word
              << ' ' << actual << '\n';
}

int main() {
    check("banana", 3);
    check("sky", 0);
    check("Apple", 2);
}

